   var draft=CatalogPreparation.Draft("Vehicle traction test ramp",CatalogKind.RoadAssembly,AssetSource.ImportedModel,null,"User supplied Low_Poly_Vehicle_Traction_Test_Ramp.blend; SHA256 283B97A7611621392919F6EB0D274D56199F4E95AB70235E6F8D53613F0DB66E. Studio excluded; source preserved and embedded text not executed.");draft.id=Id;draft.creationSourcePath="SourceAssets/TractionTestRamp/Low_Poly_Vehicle_Traction_Test_Ramp.blend";
