    foreach(var t in frames.Where(t=>t.name.StartsWith("Basis",StringComparison.Ordinal)))UnityEngine.Object.DestroyImmediate(t.gameObject);
    foreach(var anchor in root.GetComponentsInChildren<AssetAnchor>())UnityEngine.Object.DestroyImmediate(anchor.gameObject);
    var toe=CatalogPreparation.Anchor(root.transform,"road-a",AnchorRole.RoadConnection,new Vector3(0,0,-8));toe.interfaceId="traction-lane-6m";toe.transform.localRotation=Quaternion.Euler(0,180,0);var top=CatalogPreparation.Anchor(root.transform,"road-b",AnchorRole.RoadConnection,new Vector3(0,3.2f,8));top.interfaceId=toe.interfaceId;PrefabUtility.SaveAsPrefabAsset(root,path);
