  public static void PlacePrepared(Scene scene){var a=CatalogPreparation.Library().Find(Id);if(!a||!a.prefab)return;var existing=All<CatalogPlacement>(scene).SingleOrDefault(p=>p.placementId=="pinefall-traction-ramp");if(existing)return;var old=All<Transform>(scene).SingleOrDefault(t=>t.name=="SLOPE | traction test");if(!old)return;var pos=old.position;var direction=Vector3.ProjectOnPlane(old.forward,Vector3.up).normalized;float scale=old.lossyScale.z/16.080668f;var rotation=Quaternion.LookRotation(direction,Vector3.up);var terrain=All<Terrain>(scene).Single();var toe=pos+rotation*Vector3.back*(8*scale);pos.y=terrain.SampleHeight(toe)+terrain.transform.position.y+.01f;
   var go=(GameObject)PrefabUtility.InstantiatePrefab(a.prefab,scene);Undo.RegisterCreatedObjectUndo(go,"Place imported traction ramp");go.name="Traction test ramp | prepared imported assembly";go.transform.SetParent(old.parent,true);go.transform.SetPositionAndRotation(pos,rotation);go.transform.localScale=Vector3.one*scale;var p=go.GetComponent<CatalogPlacement>();p.placementId="pinefall-traction-ramp";PrefabUtility.RecordPrefabInstancePropertyModifications(p);PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);Undo.DestroyObjectImmediate(old.gameObject);
  }
  [MenuItem("Snowglow/Asset intake/Import traction test ramp")]
  public static void Install(){checks=0;Check(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var scene=SceneManager.GetActiveScene();Check(scene.path==SceneValidation.ScenePath,"open Pinefall");Directory.CreateDirectory(Logs);SceneValidation.Validate(scene);Check(EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before-"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity",true),"backup");var snow=All<SnowField>(scene).Single();var original=snow.seed;string values=JsonUtility.ToJson(original.grid);var poses=All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,p=>Pose(p.transform));var fleet=All<MachineController>(scene).ToDictionary(p=>p.name,p=>Pose(p.transform));var hashes=snow.GetComponentsInChildren<MeshFilter>().Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh)).Concat(All<Terrain>(scene).Select(t=>AssetDatabase.GetAssetPath(t.terrainData))).Concat(new[]{AssetDatabase.GetAssetPath(original)}).Where(p=>!string.IsNullOrEmpty(p)).Distinct().ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p));var a=Prepare(snow.palette.snow);Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();bool saved=false;
   try{PlacePrepared(scene);Physics.SyncTransforms();Validate(scene);var revision=UnityEngine.Object.Instantiate(original);int changed=0;for(int i=0;i<revision.grid.blocked.Length;i++){bool b=Physics.CheckBox(new Vector3(revision.grid.X(i),SnowField.Ground+.85f,revision.grid.Z(i)),new Vector3(SnowVolumeGrid.Cell*.45f,.65f,SnowVolumeGrid.Cell*.45f),Quaternion.identity,1<<0,QueryTriggerInteraction.Ignore);if(b!=revision.grid.blocked[i]){revision.grid.blocked[i]=b;changed++;}}if(changed>0){AssetDatabase.CreateAsset(revision,AssetDatabase.GenerateUniqueAssetPath(CatalogPreparation.Root+"/SceneData/TractionRampSnowObstacles.asset"));Undo.RecordObject(snow,"Update ramp obstacle flags");snow.seed=revision;EditorUtility.SetDirty(snow);}else UnityEngine.Object.DestroyImmediate(revision);
    var mask=snow.seed.grid.blocked;snow.seed.grid.blocked=original.grid.blocked;Check(values==JsonUtility.ToJson(snow.seed.grid),"snow quantities changed");snow.seed.grid.blocked=mask;foreach(var p in All<CatalogPlacement>(scene).Where(p=>poses.ContainsKey(p.placementId??"")))Check(poses[p.placementId]==Pose(p.transform),"existing catalog moved "+p.placementId);foreach(var m in All<MachineController>(scene))Check(fleet[m.name]==Pose(m.transform),"fleet moved");foreach(var h in hashes)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"source asset changed");SceneValidation.Validate(scene);MechanicsChecks.Run();Views(scene);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"save");saved=true;Undo.CollapseUndoOperations(group);scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);Validate(scene);SceneValidation.Validate(scene);MechanicsChecks.Run();foreach(var h in hashes)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"original asset changed after reopen");var placed=All<CatalogPlacement>(scene).Single(p=>p.placementId=="pinefall-traction-ramp");string rampPose=Pose(placed.transform);PlacePrepared(scene);Check(rampPose==Pose(placed.transform)&&All<CatalogPlacement>(scene).Count(p=>p.placementId=="pinefall-traction-ramp")==1,"repeat moved/duplicated ramp");
