  public static void Shorten(bool halfOriginal=false,float lengthFraction=.5f,float widthFraction=.75f){
   Check(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var scene=SceneManager.GetActiveScene();Check(scene.path==SceneValidation.ScenePath,"open Pinefall");Directory.CreateDirectory(Logs);Check(EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before-shortening-"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity",true),"resize backup");var ramp=All<CatalogPlacement>(scene).Single(p=>p.placementId=="pinefall-traction-ramp").transform;var before=ramp.localScale;var pos=ramp.position;var rot=ramp.rotation;Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();Undo.RecordObject(ramp,"Shorten traction ramp to 75 percent");var target=before;if(halfOriginal){const float originalScale=28f/16.080668f;target.x=originalScale*widthFraction;target.z=originalScale*lengthFraction;}else target.z*=.75f;ramp.localScale=target;PrefabUtility.RecordPrefabInstancePropertyModifications(ramp);try{Install();var after=All<CatalogPlacement>(SceneManager.GetActiveScene()).Single(p=>p.placementId=="pinefall-traction-ramp").transform;Check((after.localScale-target).sqrMagnitude<1e-10f&&Vector3.Distance(after.position,pos)<.00001f&&Quaternion.Angle(after.rotation,rot)<.001f,"saved resize mismatch");File.WriteAllText(Logs+(halfOriginal?"/Resize-"+lengthFraction.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+"-"+widthFraction.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+".txt":"/Shortening.txt"),"PASS: saved/reopened scale "+before.ToString("R")+" -> "+after.localScale.ToString("R")+(halfOriginal?". Length "+(lengthFraction*100)+" percent and width "+(widthFraction*100)+" percent of original; height, position and rotation retained.":". Length 75 percent; width, height, position and rotation retained.")+" Collision, source incline/crest samples, scene and 19 snow checks passed. See Validation.txt. Driving and A07 untested.");}catch{Undo.RevertAllDownToGroup(group);throw;}
  }
  static void Validate(Scene scene){var p=All<CatalogPlacement>(scene).Single(x=>x.placementId=="pinefall-traction-ramp");Check(PrefabUtility.IsPartOfPrefabInstance(p),"disconnected ramp");Check(!All<Transform>(scene).Any(t=>t.name=="SLOPE | traction test"),"primitive remains");Check(p.GetComponentsInChildren<Renderer>().Length==2&&p.GetComponentsInChildren<MeshCollider>().Length==2&&p.GetComponentsInChildren<BoxCollider>().Length==0,"renderer/collision counts");Check(!p.GetComponentsInChildren<Light>(true).Any()&&!p.GetComponentsInChildren<Rigidbody>().Any(),"unexpected light/body");Check(p.GetComponentsInChildren<AssetAnchor>().Count(a=>a.role==AnchorRole.RoadConnection)==2,"road anchors");Physics.SyncTransforms();var wedge=p.GetComponentsInChildren<MeshCollider>().Single(c=>c.name=="CollisionWedge");float scale=p.transform.lossyScale.x;
   foreach(float x in new[]{-2f,0,2})foreach(float z in new[]{-7.9f,-6,-2,2,5.5f,6.5f,7.7f}){float y=Mathf.Min(z+8,14)*(3.2f/14);var point=p.transform.TransformPoint(new Vector3(x,y,z));Check(wedge.Raycast(new Ray(point+Vector3.up*20,Vector3.down),out var hit,40),"deck collision missing");Check(Mathf.Abs(hit.point.y-point.y)<.025f,"deck height mismatch "+hit.point+" / "+point);Check(Vector3.Angle(hit.normal,p.transform.localToWorldMatrix.inverse.transpose.MultiplyVector(z<6?new Vector3(0,1,-3.2f/14):Vector3.up).normalized)<.2f,"deck normal "+hit.normal+" at z="+z);}
   var toe=p.transform.TransformPoint(new Vector3(0,0,-8));var terrain=All<Terrain>(scene).Single();Check(Mathf.Abs(toe.y-terrain.SampleHeight(toe)-terrain.transform.position.y-.01f)<.025f,"toe floats or buried");var stop=p.GetComponentsInChildren<MeshCollider>().Single(c=>c.name=="CollisionStop");Check(Vector3.Dot(stop.bounds.center-p.transform.position,p.transform.forward)>7*p.transform.lossyScale.z,"stop is not at crest");Check(stop.bounds.center.y>p.transform.position.y+3*scale,"rear stop height");
  }
  static void Views(Scene scene){var ramp=All<CatalogPlacement>(scene).Single(p=>p.placementId=="pinefall-traction-ramp");foreach(var direction in new[]{new Vector3(.6f,.5f,-1),new Vector3(-.6f,.5f,1),new Vector3(1,.25f,0)}){var preview=new PreviewRenderUtility();try{var copy=UnityEngine.Object.Instantiate(ramp.gameObject);copy.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);preview.AddSingleGO(copy);var rs=copy.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);preview.camera.orthographic=true;preview.camera.orthographicSize=b.extents.magnitude*1.05f;preview.camera.aspect=1.5f;preview.camera.nearClipPlane=.03f;preview.camera.farClipPlane=300;preview.camera.transform.position=b.center+direction.normalized*70;preview.camera.transform.LookAt(b.center);preview.camera.backgroundColor=new Color(.3f,.4f,.47f);preview.camera.clearFlags=CameraClearFlags.SolidColor;preview.ambientColor=Color.gray;preview.lights[0].intensity=1.1f;preview.lights[0].transform.rotation=preview.camera.transform.rotation;preview.BeginStaticPreview(new Rect(0,0,1200,800));preview.Render(true);var image=preview.EndStaticPreview();File.WriteAllBytes(Logs+"/Ramp-"+(direction.z<0?"toe":direction.z>0?"crest":"side")+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{preview.Cleanup();}}}
